function getStatData(){
  var all = getAllVariables() || {};
  var d = _.get(all, 'stat_data', {});
  if (!d || Object.keys(d).length === 0) {
    var m = getVariables({ type: 'message' }) || {};
    d = _.get(m, 'stat_data', {});
  }
  return d || {};
}

function setText(id, val){
  var el = document.getElementById(id);
  if (el) el.textContent = val;
}

function dots(containerId, numId, val){
  var n = Math.max(0, Math.min(100, parseInt(val) || 0));
  var f = Math.floor(n / 10);
  var h = (n % 10) >= 5;
  var box = document.getElementById(containerId);
  if (!box) return;
  box.textContent = '';
  for (var i = 0; i < 10; i++) {
    var dot = document.createElement('span');
    var level = i < 3 ? 'level-low' : (i < 7 ? 'level-mid' : 'level-high');
    var cls = 'gf-dot ' + level;
    if (i < f) cls += ' filled';
    else if (i === f && h) cls += ' half';
    dot.className = cls;
    box.appendChild(dot);
  }
  var numEl = document.getElementById(numId);
  if (numEl) numEl.textContent = n + ' / 100';
}

function renderClothes(d, prefix, containerId){
  var keys = ['外衣','内搭','贴身层','下装','鞋袜','发饰','配饰'];
  var box = document.getElementById(containerId);
  if (!box) return;
  box.textContent = '';
  keys.forEach(function(k){
    var val = _.get(d, prefix + '.服饰.' + k, '');
    if (!val) return;
    var item = document.createElement('div');
    item.className = 'gf-clo-item';
    var label = document.createElement('div');
    label.className = 'gf-clo-label';
    label.textContent = k;
    var desc = document.createElement('div');
    desc.className = 'gf-clo-desc';
    desc.textContent = val;
    item.appendChild(label);
    item.appendChild(desc);
    box.appendChild(item);
  });
}

function populate(){
  var d = getStatData();

  setText('gf-time', _.get(d, '当前时间', '') || '午后');
  setText('gf-date', _.get(d, '当前年月', '') || '南宋绍兴十七年二月十五日');
  setText('gf-weather', _.get(d, '天气', '') || '细雨');

  setText('gf-bz-loc', _.get(d, '白素贞.当前位置', '') || '西湖断桥');
  dots('gf-bz-dots', 'gf-bz-num', _.get(d, '白素贞.好感度', 0));
  setText('gf-bz-appear', _.get(d, '白素贞.外貌', ''));
  renderClothes(d, '白素贞', 'gf-bz-clothes');
  setText('gf-bz-pose', _.get(d, '白素贞.姿势', ''));
  setText('gf-bz-mind', _.get(d, '白素贞.心理', ''));

  setText('gf-xq-loc', _.get(d, '小青.当前位置', '') || '西湖断桥');
  dots('gf-xq-dots', 'gf-xq-num', _.get(d, '小青.好感度', 0));
  setText('gf-xq-appear', _.get(d, '小青.外貌', ''));
  renderClothes(d, '小青', 'gf-xq-clothes');
  setText('gf-xq-pose', _.get(d, '小青.姿势', ''));
  setText('gf-xq-mind', _.get(d, '小青.心理', ''));
}

function initTabs(){
  var tabs = document.querySelectorAll('.gf-tab');
  var panels = document.querySelectorAll('.gf-char');
  tabs.forEach(function(tab){
    tab.addEventListener('click', function(){
      if (tab.classList.contains('active')) return;
      tabs.forEach(function(t){ t.classList.remove('active'); t.setAttribute('aria-selected', 'false'); });
      panels.forEach(function(p){ p.classList.remove('active'); });
      tab.classList.add('active');
      tab.setAttribute('aria-selected', 'true');
      var panel = document.getElementById(tab.getAttribute('data-panel'));
      if (panel) panel.classList.add('active');
    });
  });
}

async function init(){
  await waitGlobalInitialized('Mvu');
  initTabs();
  populate();
  eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, function(){
    populate();
  });
}

$(errorCatched(init));
</script>
